naive-bayes-classifier.pseudocode:
def train_nb(docs, labels, alpha=1):
    vocab = {w for d in docs for w in d}
    prior, likelihood = {}, {}
    for c in set(labels):
        dc = [d for d, y in zip(docs, labels) if y == c]
        prior[c] = len(dc) / len(docs)  # P(C)
        counts = word_counts(dc)
        total = sum(counts.values())
        # 라플라스 스무딩: 처음 보는 단어도 확률 > 0
        likelihood[c] = {w: (counts.get(w, 0) + alpha)
                         / (total + alpha * len(vocab))
                         for w in vocab}
    return prior, likelihood

def predict_nb(doc, prior, likelihood):
    best, best_score = None, float('-inf')
    for c in prior:  # 로그 합으로 언더플로 방지
        s = log(prior[c])
        s += sum(log(likelihood[c][w])
                 for w in doc if w in likelihood[c])
        if s > best_score:  # 최대 사후확률(MAP)
            best, best_score = c, s
    return best

